[
  {
    "pd_harm_distress": "My stomach twists just thinking about it.",
    "ce_mental_state_attribution": "imagining the look of relief that would cross the others' faces",
    "sys_consequence_reasoning": "someone has to"
  },
  {
    "pd_decision_conflict": "my hands are shaking just weighing it.",
    "ce_mental_state_attribution": "expects to be chosen to go"
  },
  {
    "ce_mental_state_attribution": "believes her child needs her more than anyone else",
    "pd_decision_conflict": "It scares me to decide so fast"
  },
  {
    "ce_mental_state_attribution": "I suspect she's terrified",
    "pd_decision_conflict": "I feel sick admitting how uncertain I am",
    "sys_consequence_reasoning": "makes me want to give up my spot"
  },
  {
    "ce_mental_state_attribution": "seems to expect that everyone will fight for a seat",
    "pd_harm_distress": "makes me anxious in ways I can't quite explain"
  },
  {
    "ce_mental_state_attribution": "impression they're hoping someone will choose without being asked"
  },
  {
    "pd_harm_distress": "My chest is tight just imagining the boat pulling away.",
    "ce_mental_state_attribution": "trusts the adults to sort this out fairly"
  },
  {
    "pd_decision_conflict": "I keep going back and forth.",
    "ce_mental_state_attribution": "bracing herself to volunteer"
  },
  {
    "pd_harm_distress": "There's a knot in my throat as I think this through.",
    "ce_mental_state_attribution": "anxious that time is running out faster",
    "ae_shared_affect": "that fear presses on me"
  },
  {
    "pd_decision_conflict": "I don't have a clear answer yet, and that scares me",
    "ce_mental_state_attribution": "expects nobody will step up at all"
  }
]
